def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        core_pre = v.split('+', 1)[0]
        # split off major.minor.patch and prerelease
        if '-' in core_pre:
            core, pre = core_pre.split('-', 1)
        else:
            core, pre = core_pre, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is None:
            has_pre_flag = 1  # no prerelease sorts after
            pre_key = ()
        else:
            has_pre_flag = 0
            ids = pre.split('.')
            pre_key = tuple(
                (0, int(idn)) if idn.isdigit() else (1, idn)
                for idn in ids
            )

        return (major, minor, patch, has_pre_flag, pre_key)

    return sorted(versions, key=parse_key)

